insert into pricing_profiles (code, name, method, labor_profile, equipment_profile, status) values
  ('PP-AVG', 'Average Market', 'parallel', 'Regional average', 'Regional blended', 'active'),
  ('PP-UNION', 'Union', 'stacked', 'Union wage/fringe', 'Company/rental', 'active'),
  ('PP-CUSTOM', 'Custom Company', 'parallel', 'Tenant-defined', 'Tenant-defined', 'active')
on conflict do nothing;

insert into markup_components (company_id, pricing_profile_id, code, label, percent, basis, sequence)
select null, p.id, v.code, v.label, v.pct, 'profile_default', v.seq
from (values
  ('PP-AVG', 'OH', 'Overhead', 0.1::numeric, 10),
  ('PP-AVG', 'PROFIT', 'Profit', 0.12::numeric, 20),
  ('PP-AVG', 'CONT', 'Contingency', 0.03::numeric, 30),
  ('PP-UNION', 'OH', 'Overhead', 0.12::numeric, 10),
  ('PP-UNION', 'PROFIT', 'Profit', 0.12::numeric, 20),
  ('PP-UNION', 'CONT', 'Contingency', 0.04::numeric, 30),
  ('PP-CUSTOM', 'OH', 'Overhead', 0.1::numeric, 10),
  ('PP-CUSTOM', 'PROFIT', 'Profit', 0.15::numeric, 20),
  ('PP-CUSTOM', 'CONT', 'Contingency', 0.03::numeric, 30)
) as v(profile_code, code, label, pct, seq)
join pricing_profiles p on p.code = v.profile_code and p.company_id is null and p.enterprise_group_id is null
on conflict do nothing;


